 */
export const getAllUsers = async (limit = 50, offset = 0) => {
  if (typeof limit !== 'number' || limit <= 0 || limit > 1000) {
    throw new Error('Limit must be a number between 1 and 1000');
  }
  if (typeof offset !== 'number' || offset < 0) {
    throw new Error('Offset must be a non-negative number');
  }

  const client = await pool.connect();

  try {
    const query = `
      SELECT id, email, name, age, status, created_at, updated_at
      FROM users
      ORDER BY id
      LIMIT $1 OFFSET $2
    `;

    const result = await client.query(query, [limit, offset]);

    return result.rows;
  } catch (error) {
    console.error('Error fetching users:', error.message);
    throw new Error(`Failed to fetch users: ${error.message}`);
  } finally {
    client.release();
  }
};

/**
 * Update user by ID
 * @param {number} id - User ID
 * @param {Object} updates - Object containing fields to update
 * @returns {Promise<Object|null>} - Updated user object or null if not found
 */
export const updateUser = async (id, updates) => {
  validateId(id);
  validateUserInput(updates, true);

  if (Object.keys(updates).length === 0) {
    throw new Error('No updates provided');
  }

  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    // Build dynamic SET clause with parameterized queries
    const allowedFields = ['email', 'name', 'password_hash', 'age', 'status'];
    const setClauses = [];
    const values = [];
    let paramIndex = 1;

    for (const field of allowedFields) {
      if (updates[field] !== undefined) {
        setClauses.push(`${field} = $${paramIndex}`);
        values.push(field === 'email' ? updates[field].toLowerCase() : updates[field]);
        paramIndex++;
      }
    }

    if (setClauses.length === 0) {
      throw new Error('No valid fields to update');
    }

    setClauses.push(`updated_at = NOW()`);
    values.push(id);

    const query = `
      UPDATE users
      SET ${setClauses.join(', ')}
      WHERE id = $${paramIndex}
      RETURNING id, email, name, age, status, created_at, updated_at
    `;

    const result = await client.query(query, values);

    await client.query('COMMIT');

    return result.rows[0] || null;
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Error updating user:', error.message);
    throw new Error(`Failed to update user: ${error.message}`);
  } finally {
    client.release();
  }
};

/**
 * Delete user by ID
 * @param {number} id - User ID
 * @returns {Promise<boolean>} - True if deleted, false if not found
 */
export const deleteUser = async (id) => {
  validateId(id);

  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    const query = 'DELETE FROM users WHERE id = $1 RETURNING id';
    const result = await client.query(query, [id]);

    await client.query('COMMIT');

    return result.rowCount > 0;
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Error deleting user:', error.message);
    throw new Error(`Failed to delete user: ${error.message}`);
  } finally {
    client.release();
  }
};

/**
 * Get user count (useful for pagination)
 * @returns {Promise<number>} - Total number of users
 */
export const getUserCount = async () => {
  const client = await pool.connect();

  try {
    const query = 'SELECT COUNT(*) as count FROM users';
    const result = await client.query(query);

    return parseInt(result.rows[0].count, 10);
  } catch (error) {
    console.error('Error counting users:', error.message);
    throw new Error(`Failed to count users: ${error.message}`);
  } finally {
    client.release();
  }
};

/**
 * Close the database connection pool
 * @returns {Promise<void>}
 */
export const closeDatabase = async () => {
  try {
    await pool.end();
    console.log('Database pool closed successfully');
  } catch (error) {
    console.error('Error closing database pool:', error.message);
    throw error;
  }
};

