    // pre-computed rainbow-table attacks impossible and slowing brute-force.
    // Never store passwords in plaintext or with fast hashes (MD5, SHA-*).
    const passwordHash = await bcrypt.hash(newPassword, BCRYPT_SALT_ROUNDS);

