router.get('/run-command', async (req, res) => {
  const requestedCmd = req.query.cmd;

  // â”€â”€ 4a. Presence check â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  if (!requestedCmd) {
    return res.status(400).json({
      success: false,
      error: 'Missing required query parameter: cmd',
    });
