    // Build URL with query parameters
    const baseUrl = endpoint 
      ? `https://api.example.com/${endpoint}`
      : `https://api.example.com/resource/${identifier}`;

    const url = new URL(baseUrl);
    if (query) {
      Object.entries(query).forEach(([key, value]) => {
