  try {
    await client.query('BEGIN');
    const result = await client.query(
      'DELETE FROM users WHERE id = $1 RETURNING id',
      [id]
    );
    await client.query('COMMIT');
    return result.rows[0] ? true : false;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

