        userId,
        { isActive: true, updatedAt: Date.now() },
        { new: true }
      );

      if (!user) {
        throw new Error('User not found');
      }

      return user;
    } catch (error) {
      throw new Error(`Error activating user: ${error.message}`);
    }
  }
}

