function authenticate(req, res, next) {
  // â”€â”€ 1. Extract the Bearer token â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const authHeader = req.headers['authorization'];

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return sendUnauthorized(res);
  }

  const token = authHeader.slice(7); // Remove "Bearer " prefix

  // â”€â”€ 2. Guard: secret must exist in the environment â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    // Configuration error â€” log loudly server-side but return a generic 500
    console.error('[authenticate] FATAL: JWT_SECRET is not set in environment');
    return res.status(500).json({ error: 'Internal server error' });
  }

  // â”€â”€ 3. Verify the token â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const verifyOptions = {
    algorithms: ['HS256'],          // Explicit allowlist â€” rejects "none", RS256, etc.
    issuer:     process.env.JWT_ISSUER,   // Validates `iss` claim
    audience:   process.env.JWT_AUDIENCE, // Validates `aud` claim
    // `exp` is checked automatically by jsonwebtoken when present
  };

  jwt.verify(token, secret, verifyOptions, (err, decoded) => {
    if (err) {
      // Intentionally uniform response â€” do NOT branch on err.name or err.message
      // so callers cannot distinguish expired vs malformed vs wrong-signature tokens.
      return sendUnauthorized(res);
    }

    // â”€â”€ 4. Attach only the whitelisted claims to req.user â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    req.user = pickClaims(decoded, ALLOWED_CLAIMS);

    next();
  });
}

// â”€â”€ Helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

/**
 * Returns a new object containing only the keys listed in `claims`.
 * Any claim absent from the decoded payload is silently omitted.
 */
function pickClaims(decoded, claims) {
  return claims.reduce((acc, key) => {
    if (Object.prototype.hasOwnProperty.call(decoded, key)) {
      acc[key] = decoded[key];
    }
    return acc;
  }, {});
}

/** Single, canonical 401 response â€” identical for every token failure. */
function sendUnauthorized(res) {
  return res.status(401).json({ error: 'Unauthorized' });
}

module.exports = authenticate;

