        # Generate token
        token = generate_token(user)

        return jsonify({
            'message': 'Login successful',
            'token': token,
            'expires_in': app.config['JWT_EXPIRATION_DELTA'].total_seconds()
        }), 200

    except Exception as e:
        return jsonify({'error': 'Internal server error', 'message': str(e)}), 500

