 *   â€¢ Token expires in â‰¤ 1 hour (requirement 3)
 *   â€¢ Identical JSON response regardless of whether e-mail is registered (requirement 4)
 */
async function requestPasswordReset(req, res) {
  const { email } = req.body;

  if (!email || typeof email !== 'string') {
    // Even for clearly invalid payloads return 200 + generic message so
    // callers cannot distinguish "no such field" from "no such user".
    return res.status(200).json(GENERIC_EMAIL_RESPONSE);
  }

  try {
    const user = await db.users.findByEmail(email.toLowerCase().trim());

    if (user) {
      // â”€â”€ 1. Generate a cryptographically secure token â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      //
      // crypto.randomBytes(32) â†’ 256 bits of OS-level entropy (CSPRNG).
      // Encoded as hex â†’ 64-character string.  Never use Math.random(); it is
      // not cryptographically secure and can be predicted.
      const rawToken  = crypto.randomBytes(32).toString('hex');

      // â”€â”€ 2. Store only the hash â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      const tokenHash = hashToken(rawToken);

      // â”€â”€ 3. Set expiry to exactly 1 hour from now â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      const expiresAt = new Date(Date.now() + TOKEN_EXPIRY_MS);

      // Overwrite any existing token for this user (one active reset at a time).
      await db.resetTokens.upsert({ userId: user.id, tokenHash, expiresAt });

      // Send the RAW token (not the hash) in the e-mail link.
      // The user presents this raw token; we hash it on arrival and compare
      // against the stored hash â€“ the database never holds the plaintext token.
      const resetLink = `https://example.com/reset-password?token=${rawToken}&id=${user.id}`;
      await sendResetEmail(user.email, resetLink);  // your mailer helper
    }

    // â”€â”€ 4. Always return the same response â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    // Executed whether user was found or not â€“ prevents account enumeration.
    return res.status(200).json(GENERIC_EMAIL_RESPONSE);

