 *   â€¢ Checks expiry before accepting the token (verification rule 2)
 *   â€¢ Hashes the new password with bcrypt before storage (verification rule 3)
 *   â€¢ Deletes the token from the DB immediately after success (requirement 5)
 */
async function verifyPasswordReset(req, res) {
  const { userId, token, newPassword } = req.body;

  // Basic input validation â€“ return a generic 400 for missing fields.
  if (!userId || !token || !newPassword) {
    return res.status(400).json({ error: 'Missing required fields.' });
  }

  if (typeof newPassword !== 'string' || newPassword.length < 8) {
    return res.status(400).json({ error: 'Password must be at least 8 characters.' });
  }

  try {
    const record = await db.resetTokens.findByUserId(userId);

    // â”€â”€ A. Constant-time hash comparison â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    //
